<style>
.hr-shell{position:relative}.hr-shell:before{content:"";position:absolute;inset:-24px -20px auto;height:190px;border-radius:0 0 28px 28px;background:linear-gradient(135deg,rgba(33,53,42,.07),rgba(213,170,101,.11));pointer-events:none}.hr-shell>*{position:relative;z-index:1}
.hr-stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.hr-stat-card{background:#fff;border:1px solid rgba(33,53,42,.1);border-radius:16px;padding:17px;display:flex;align-items:center;gap:13px;box-shadow:0 8px 24px rgba(33,53,42,.06)}.hr-stat-icon{width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;background:linear-gradient(145deg,rgba(33,53,42,.12),rgba(213,170,101,.2));color:var(--progga-primary);font-size:20px}.hr-stat-value{font-size:22px;font-weight:900;color:var(--progga-text);line-height:1}.hr-stat-label{font-size:12px;color:var(--progga-text-muted);margin-top:5px}
.hr-card{background:#fff;border:1px solid rgba(33,53,42,.1);border-radius:16px;box-shadow:0 10px 28px rgba(33,53,42,.065);overflow:hidden}.hr-card-header{padding:17px 19px;border-bottom:1px solid rgba(33,53,42,.08);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;background:linear-gradient(180deg,#fff,rgba(33,53,42,.02))}.hr-card-title{font-size:16px;font-weight:900;color:var(--progga-text)}.hr-card-subtitle{font-size:12px;color:var(--progga-text-muted);margin-top:3px}.hr-card-body{padding:18px}.hr-filter-grid{display:grid;grid-template-columns:2fr repeat(3,minmax(150px,1fr)) auto;gap:10px;align-items:end}.hr-filter-grid.five{grid-template-columns:2fr repeat(4,minmax(140px,1fr)) auto}.hr-search{position:relative}.hr-search i{position:absolute;left:13px;top:50%;transform:translateY(-50%);color:var(--progga-text-muted)}.hr-search input{padding-left:38px}.hr-table-loading{opacity:.55;pointer-events:none}.hr-table-avatar{width:40px;height:40px;border-radius:12px;object-fit:cover;flex-shrink:0}.hr-person{display:flex;align-items:center;gap:11px}.hr-person-name{font-weight:800;color:var(--progga-text)}.hr-person-meta{font-size:11px;color:var(--progga-text-muted);margin-top:2px}.hr-muted{font-size:12px;color:var(--progga-text-muted)}
.hr-badge{display:inline-flex;align-items:center;gap:5px;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:800;text-transform:capitalize}.hr-badge-success{background:#e7f7ed;color:#16814b}.hr-badge-danger{background:#fdeaea;color:#c63d3d}.hr-badge-warning{background:#fff3dd;color:#a86800}.hr-badge-info{background:#e9f4ff;color:#1768a7}.hr-badge-neutral{background:#f1f3f2;color:#53615a}.hr-badge-primary{background:rgba(33,53,42,.1);color:var(--progga-primary)}
.report-pagination-wrap{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:14px 16px;border-top:1px solid var(--progga-border-light)}.report-pagination{display:flex;gap:5px;align-items:center;flex-wrap:wrap}.report-page-link{display:inline-flex;align-items:center;justify-content:center;min-width:34px;height:34px;padding:0 10px;border:1px solid var(--progga-border-light);border-radius:8px;background:#fff;color:var(--progga-primary);font-size:12px;font-weight:800;text-decoration:none}.report-page-link:hover{background:rgba(33,53,42,.06);color:var(--progga-primary)}.report-page-link.active{background:var(--progga-primary);color:#fff;border-color:var(--progga-primary)}.report-page-link.disabled{opacity:.45;pointer-events:none;color:var(--progga-text-muted)}
.hr-modal .modal-content{border:0;border-radius:17px;overflow:hidden;box-shadow:0 24px 70px rgba(0,0,0,.18)}.hr-modal .modal-header{padding:17px 20px;background:linear-gradient(135deg,var(--progga-primary),#355b46);color:#fff;border:0}.hr-modal .modal-header .btn-close{filter:invert(1)}.hr-modal .modal-body{padding:20px}.hr-modal .modal-footer{padding:14px 20px 18px}.hr-section-title{font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.06em;color:var(--progga-primary);margin:5px 0 12px;padding-bottom:8px;border-bottom:1px solid rgba(33,53,42,.1)}
.hr-shell .select2-container{width:100%!important;min-width:0}.hr-shell .select2-container--progga-theme .select2-selection--single{height:42px}.hr-shell .select2-container--progga-theme .select2-selection--single .select2-selection__rendered{line-height:40px}.hr-shell .select2-container--progga-theme .select2-selection--single .select2-selection__arrow{height:40px}.hr-modal .select2-container{width:100%!important}.select2-container--open{z-index:2100!important}.flatpickr-day.selected{background:var(--progga-primary);border-color:var(--progga-primary)}
.hr-segmented{display:flex;gap:7px;padding:5px;background:rgba(33,53,42,.05);border-radius:11px;flex-wrap:wrap}.hr-segmented button{border:0;background:transparent;padding:8px 13px;border-radius:8px;font-size:12px;font-weight:800;color:var(--progga-text-muted)}.hr-segmented button.active{background:#fff;color:var(--progga-primary);box-shadow:0 3px 12px rgba(33,53,42,.1)}
.hr-empty{padding:42px 18px;text-align:center;color:var(--progga-text-muted)}.hr-empty i{display:block;font-size:30px;margin-bottom:8px;color:rgba(33,53,42,.35)}
@media(max-width:1199px){.hr-filter-grid,.hr-filter-grid.five{grid-template-columns:repeat(3,minmax(0,1fr))}.hr-search{grid-column:span 2}.hr-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767px){.hr-filter-grid,.hr-filter-grid.five{grid-template-columns:1fr}.hr-search{grid-column:auto}.hr-stat-grid{grid-template-columns:1fr}.hr-card-header .progga-btn{width:100%;justify-content:center}.report-pagination-wrap{align-items:flex-start}.report-pagination{width:100%}.report-page-link:first-child,.report-page-link:last-child{display:none}}
</style>


<style>
