.hr-profile-code{font-size:13px;font-weight:800;color:var(--progga-text-muted);margin-top:4px}.hr-profile-contact{display:grid;gap:8px;font-size:13px;color:var(--progga-text-muted);min-width:220px}.hr-profile-contact i{color:var(--progga-primary);margin-right:7px}
