.hr-info-list{display:grid;gap:0}.hr-info-list>div{display:flex;justify-content:space-between;gap:18px;padding:10px 0;border-bottom:1px solid rgba(33,53,42,.08);font-size:13px}.hr-info-list>div:last-child{border-bottom:0}.hr-info-list span{color:var(--progga-text-muted)}.hr-info-list strong{text-align:right;color:var(--progga-text)}
.hr-money-box{padding:14px;border-radius:13px;background:rgba(33,53,42,.055);border:1px solid rgba(33,53,42,.08);display:flex;flex-direction:column;gap:4px}.hr-money-box span{font-size:11px;color:var(--progga-text-muted);text-transform:uppercase;letter-spacing:.04em}.hr-money-box strong{font-size:17px;color:var(--progga-primary)}
.hr-roster-strip{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}.hr-roster-day{padding:11px 8px;border:1px solid var(--progga-border-light);border-radius:12px;text-align:center;background:#fff}.hr-roster-day span,.hr-roster-day small{display:block;font-size:10px;color:var(--progga-text-muted)}.hr-roster-day strong{display:block;font-size:13px;margin:3px 0;color:var(--progga-text)}
.hr-balance-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid rgba(33,53,42,.08)}.hr-balance-row:last-child{border-bottom:0}
.hr-estimated-gross{display:flex;align-items:flex-end;flex-direction:column;gap:2px;padding:9px 13px;border-radius:12px;background:rgba(33,53,42,.07)}.hr-estimated-gross span{font-size:10px;color:var(--progga-text-muted);text-transform:uppercase}.hr-estimated-gross strong{font-size:18px;color:var(--progga-primary)}
.hr-manual-component{font-size:12px;color:var(--progga-text-muted);padding:10px 12px;border-radius:9px;background:rgba(33,53,42,.045)}.salary-component-disabled{opacity:.52}.salary-component-disabled .hr-manual-component{pointer-events:none}
.hr-salary-component-table .input-group-text{font-size:12px;background:#f6f7f6;border-color:var(--progga-border-light)}
