@media(max-width:767px){.hr-filter-grid-employees{grid-template-columns:1fr}.hr-filter-grid-employees .hr-search{grid-column:auto}.hr-profile-hero{display:block;text-align:center}.hr-profile-image-lg{margin-bottom:14px}.hr-profile-contact{grid-template-columns:1fr;text-align:left;margin-top:16px}.hr-roster-strip{grid-template-columns:repeat(2,minmax(0,1fr))}.hr-form-actions{position:static}.hr-form-actions .progga-btn{flex:1;justify-content:center}}
