<style>
.payroll-run-filter{grid-template-columns:minmax(260px,2fr) minmax(170px,1fr) minmax(170px,1fr) auto}.payroll-item-filter{grid-template-columns:minmax(280px,2fr) minmax(190px,1fr) minmax(180px,1fr) auto}
.payroll-current-banner{background:linear-gradient(135deg,#fff,rgba(213,170,101,.14))}.payroll-run-hero{border-left:4px solid var(--progga-secondary)}
.payroll-five-stats{grid-template-columns:repeat(5,minmax(0,1fr))}.payroll-item-stats{grid-template-columns:repeat(4,minmax(0,1fr))}.payroll-money{font-size:17px;white-space:nowrap}
.payroll-check-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.payroll-check-card{border:1px solid var(--progga-border-light);border-radius:13px;padding:14px;background:#fff}.payroll-check-card span{display:block;font-size:11px;text-transform:uppercase;color:var(--progga-text-muted);font-weight:800}.payroll-check-card strong{display:block;font-size:24px;color:var(--progga-primary);margin-top:4px}.payroll-check-card.warning{background:#fff9ef;border-color:#f1dfb8}
.payroll-step-list{display:grid;gap:13px}.payroll-step-list>div{display:flex;gap:11px;align-items:flex-start}.payroll-step-list>div>span{width:29px;height:29px;border-radius:9px;background:var(--progga-primary);color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:900;flex-shrink:0}.payroll-step-list p{margin:0}.payroll-step-list strong,.payroll-step-list small{display:block}.payroll-step-list small{color:var(--progga-text-muted);margin-top:2px}
.payroll-missing-list{display:flex;gap:7px;flex-wrap:wrap}.payroll-missing-list a{padding:6px 9px;border-radius:8px;background:#fff;color:var(--progga-danger);font-size:11px;font-weight:800;border:1px solid rgba(179,48,48,.15)}
.payroll-confirm-row{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--progga-border-light);border-radius:12px;padding:13px;margin-bottom:10px;cursor:pointer}.payroll-confirm-row input{margin-top:4px}.payroll-confirm-row strong,.payroll-confirm-row small{display:block}.payroll-confirm-row small{color:var(--progga-text-muted);margin-top:2px}
.payroll-attendance-chips{display:flex;gap:4px;flex-wrap:wrap}.payroll-attendance-chips span{font-size:10px;font-weight:900;padding:3px 6px;border-radius:7px;background:#f1f3f2;color:#53615a}.payroll-attendance-chips .good{background:#e7f7ed;color:#16814b}.payroll-attendance-chips .warn{background:#fff3dd;color:#a86800}.payroll-attendance-chips .bad{background:#fdeaea;color:#c63d3d}
.payroll-employee-hero{display:flex;align-items:center;gap:14px}.payroll-avatar{width:58px;height:58px;border-radius:18px;background:linear-gradient(135deg,var(--progga-primary),#355b46);color:var(--progga-secondary);display:flex;align-items:center;justify-content:center;font-size:23px;font-weight:900;flex-shrink:0}
.payroll-component-table .input-group-text{background:#f6f7f6;border-color:var(--progga-border-light)}.payroll-calculated-note{font-size:10px;color:var(--progga-text-muted);margin-top:4px}.payroll-overridden-row{background:#fff9ef}.payroll-overridden-row td:first-child{box-shadow:inset 3px 0 0 var(--progga-warning)}.payroll-payment-amount{border-radius:14px;background:rgba(33,53,42,.06);padding:15px;display:flex;align-items:center;justify-content:space-between}.payroll-payment-amount span{font-size:12px;color:var(--progga-text-muted)}.payroll-payment-amount strong{font-size:21px;color:var(--progga-primary)}
