@media(max-width:1199px){.payroll-run-filter,.payroll-item-filter{grid-template-columns:repeat(2,minmax(0,1fr))}.payroll-run-filter .hr-search,.payroll-item-filter .hr-search{grid-column:span 2}.payroll-check-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.payroll-five-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:767px){.payroll-run-filter,.payroll-item-filter{grid-template-columns:1fr}.payroll-run-filter .hr-search,.payroll-item-filter .hr-search{grid-column:auto}.payroll-check-grid,.payroll-five-stats,.payroll-item-stats{grid-template-columns:1fr}.payroll-money{font-size:18px}}
