.payroll-workflow-summary{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.payroll-workflow-summary span{display:inline-flex;align-items:center;gap:5px;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:800}.payroll-workflow-summary .draft{background:#fff3dd;color:#a86800}.payroll-workflow-summary .approved{background:#e9f3fb;color:#1466a0}.payroll-workflow-summary .paid{background:#e7f7ed;color:#16814b}
